def gen(rng):
    def fmt(A, B):
        return str(len(A)) + '\n' + ' '.join(A) + '\n' + str(len(B)) + '\n' + ' '.join(B)
    def rs(alpha, lo, hi):
        return ''.join(rng.choice(alpha) for _ in range(rng.randint(lo, hi)))
    tests = [fmt(['a'], ['a']), fmt(['b'], ['a']), fmt(['abc'], ['ab']),
             fmt(['a', 'a', 'a'], ['abc']), fmt(['ab', 'abc', 'abcd'], ['abcd'])]
    for alpha in ('ab', 'abc', 'abcdefghij'):
        for _ in range(8):
            n = rng.randint(1, 8)
            m = rng.randint(1, 8)
            tests.append(fmt([rs(alpha, 1, 4) for _ in range(n)], [rs(alpha, 1, 5) for _ in range(m)]))
    letters = 'abcdefghijklmnopqrstuvwxyz'
    tests.append(fmt([rs(letters, 1, 2) for _ in range(100000)], [rs(letters, 1, 2) for _ in range(100000)]))
    A = []
    for i in range(1, 600):
        A.append('a' * i if i % 3 else 'a' * (i - 1) + 'b')
    tests.append(fmt(A, ['a' * 200000]))
    tests.append(fmt(['a' * 199999], ['a' * j for j in range(1, 600)]))
    tests.append(fmt(['a' * 199999], ['a' * 199999 + 'b']))
    tests.append(fmt(['ab'] * 100000, ['abc']))
    tests.append(fmt([rs('ab', 1, 2) for _ in range(100000)], [rs('ab', 1, 2) for _ in range(100000)]))
    return tests
